using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using BelediyeEnvanter.Data;using Microsoft.EntityFrameworkCore;
namespace BelediyeEnvanter.Controllers;
[Authorize(Roles="Yönetici")] public class UsersController(UserManager<IdentityUser> users,AppDbContext db):Controller{
public async Task<IActionResult> Index(){var list=users.Users.OrderBy(x=>x.UserName).ToList();var map=new Dictionary<string,string>();foreach(var u in list)map[u.Id]=(await users.GetRolesAsync(u)).FirstOrDefault()??"Personel";ViewBag.RoleMap=map;return View(list);}
public async Task<IActionResult> Logs()=>View(await db.AuditLogs.OrderByDescending(x=>x.Tarih).Take(500).ToListAsync());
[HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Create(string userName,string password,string role){var u=new IdentityUser{UserName=userName?.Trim(),Email=(userName?.Trim()??"")+"@belediye.local",EmailConfirmed=true};var r=await users.CreateAsync(u,password??"");if(r.Succeeded){await users.AddToRoleAsync(u,string.IsNullOrWhiteSpace(role)?"Personel":role);db.AuditLogs.Add(new(){Kullanici=User.Identity?.Name??"Bilinmiyor",Islem="Kullanıcı Ekleme",Aciklama=$"{u.UserName} kullanıcısı oluşturuldu. Rol: {role}"});await db.SaveChangesAsync();TempData["Mesaj"]="Kullanıcı başarıyla oluşturuldu.";}else{var hata=string.Join(" ",r.Errors.Select(e=>e.Code switch{"PasswordTooShort"=>"Parola en az 8 karakter olmalıdır.","DuplicateUserName"=>"Bu kullanıcı adı zaten kayıtlı.","PasswordRequiresUpper"=>"Parolada büyük harf zorunluluğu var." ,_=>e.Description}));TempData["Hata"]=hata;}return RedirectToAction(nameof(Index));}
[HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> SetRole(string id,string role){var u=await users.FindByIdAsync(id);if(u!=null&&u.UserName!="admin"&&(role=="Personel"||role=="Yönetici")){var old=await users.GetRolesAsync(u);await users.RemoveFromRolesAsync(u,old);await users.AddToRoleAsync(u,role);db.AuditLogs.Add(new(){Kullanici=User.Identity?.Name??"Bilinmiyor",Islem="Rol Değişikliği",Aciklama=$"{u.UserName} rolü {role} olarak değiştirildi."});await db.SaveChangesAsync();}return RedirectToAction(nameof(Index));}
public async Task<IActionResult> Delete(string id){var u=await users.FindByIdAsync(id);if(u!=null&&u.UserName!="admin"){var ad=u.UserName;await users.DeleteAsync(u);db.AuditLogs.Add(new(){Kullanici=User.Identity?.Name??"Bilinmiyor",Islem="Kullanıcı Silme",Aciklama=$"{ad} kullanıcısı silindi."});await db.SaveChangesAsync();}return RedirectToAction(nameof(Index));}}
